USE venomoncodb;

-- Source-traceable starter records. These are intentionally few; the project does not pad to a target count.
ON DUPLICATE KEY UPDATE cancer_name=VALUES(cancer_name);

ON DUPLICATE KEY UPDATE description=VALUES(description);

ON DUPLICATE KEY UPDATE title=VALUES(title),source_url=VALUES(source_url);

ON DUPLICATE KEY UPDATE venom_group=VALUES(venom_group),common_name=VALUES(common_name);

ON DUPLICATE KEY UPDATE sequence=VALUES(sequence),sequence_length=VALUES(sequence_length),source_traceability=VALUES(source_traceability),primary_source_verified=VALUES(primary_source_verified);

-- Peptide-source links
SELECT p.peptide_id,o.organism_id,pub.publication_id,'Primary publication identifies the venom source.' FROM peptides p JOIN source_organisms o ON o.scientific_name='Lycosa singoriensis' JOIN publications pub ON pub.pmid='29763387' WHERE p.public_id='LIT-LYCOSIN-I' AND NOT EXISTS (SELECT 1 FROM peptide_sources x WHERE x.peptide_id=p.peptide_id AND x.organism_id=o.organism_id);
SELECT p.peptide_id,o.organism_id,pub.publication_id,'Primary publication identifies the venom source.' FROM peptides p JOIN source_organisms o ON o.scientific_name='Scorpio maurus palmatus' JOIN publications pub ON pub.doi='10.3390/toxins14100717' WHERE p.public_id='LIT-SMP24' AND NOT EXISTS (SELECT 1 FROM peptide_sources x WHERE x.peptide_id=p.peptide_id AND x.organism_id=o.organism_id);
SELECT p.peptide_id,o.organism_id,pub.publication_id,'Primary publication identifies the venom source.' FROM peptides p JOIN source_organisms o ON o.scientific_name='Buthus martensii Karsch' JOIN publications pub ON pub.pmid='30740360' WHERE p.public_id='LIT-BMK-AGAP' AND NOT EXISTS (SELECT 1 FROM peptide_sources x WHERE x.peptide_id=p.peptide_id AND x.organism_id=o.organism_id);
SELECT p.peptide_id,o.organism_id,pub.publication_id,'Primary publication identifies the venom source.' FROM peptides p JOIN source_organisms o ON o.scientific_name='Crotalus durissus terrificus' JOIN publications pub ON pub.pmid='21834748' WHERE p.public_id='LIT-CROTAMINE' AND NOT EXISTS (SELECT 1 FROM peptide_sources x WHERE x.peptide_id=p.peptide_id AND x.organism_id=o.organism_id);
SELECT p.peptide_id,o.organism_id,pub.publication_id,'Primary publication identifies the venom source.' FROM peptides p JOIN source_organisms o ON o.scientific_name='Leiurus quinquestriatus quinquestriatus' JOIN publications pub ON pub.pmid='9809993' WHERE p.public_id='LIT-CHLOROTOXIN' AND NOT EXISTS (SELECT 1 FROM peptide_sources x WHERE x.peptide_id=p.peptide_id AND x.organism_id=o.organism_id);

-- Activity evidence. Numeric IC50 is left NULL when the cited paper does not report an IC50.
SELECT 'B16-F10','Mouse','Melanoma',(SELECT cancer_type_id FROM cancer_types WHERE cancer_name='Melanoma') WHERE NOT EXISTS (SELECT 1 FROM cell_lines WHERE cell_line_name='B16-F10');
SELECT 'HepG2','Human','Liver',(SELECT cancer_type_id FROM cancer_types WHERE cancer_name='Hepatoma') WHERE NOT EXISTS (SELECT 1 FROM cell_lines WHERE cell_line_name='HepG2');
SELECT 'MCF-7','Human','Breast',(SELECT cancer_type_id FROM cancer_types WHERE cancer_name='Breast Cancer') WHERE NOT EXISTS (SELECT 1 FROM cell_lines WHERE cell_line_name='MCF-7');
SELECT 'MDA-MB-231','Human','Breast',(SELECT cancer_type_id FROM cancer_types WHERE cancer_name='Breast Cancer') WHERE NOT EXISTS (SELECT 1 FROM cell_lines WHERE cell_line_name='MDA-MB-231');
SELECT 'DU-145','Human','Prostate',(SELECT cancer_type_id FROM cancer_types WHERE cancer_name='Prostate Cancer') WHERE NOT EXISTS (SELECT 1 FROM cell_lines WHERE cell_line_name='DU-145');

SELECT p.peptide_id,cl.cell_line_id,pub.publication_id,'Cell viability / cytotoxicity','Cancer-cell viability','5 µg/mL was lethal to B16-F10 cells; no IC50 reported in the indexed abstract','PMID 21834748','Curated' FROM peptides p JOIN cell_lines cl ON cl.cell_line_name='B16-F10' JOIN publications pub ON pub.pmid='21834748' WHERE p.public_id='LIT-CROTAMINE' AND NOT EXISTS (SELECT 1 FROM activity_assays a WHERE a.peptide_id=p.peptide_id AND a.cell_line_id=cl.cell_line_id AND a.publication_id=pub.publication_id);
SELECT p.peptide_id,cl.cell_line_id,pub.publication_id,'ATP release / cell viability','Antitumor activity','Cytotoxicity against HepG2; detailed mechanisms include membrane disruption, mitochondrial dysfunction, cell-cycle arrest, apoptosis and autophagy','Toxins 2022; PMID/PMC source','Curated' FROM peptides p JOIN cell_lines cl ON cl.cell_line_name='HepG2' JOIN publications pub ON pub.doi='10.3390/toxins14100717' WHERE p.public_id='LIT-SMP24' AND NOT EXISTS (SELECT 1 FROM activity_assays a WHERE a.peptide_id=p.peptide_id AND a.cell_line_id=cl.cell_line_id AND a.publication_id=pub.publication_id);
SELECT p.peptide_id,cl.cell_line_id,pub.publication_id,'Cancer-cell assays','Tumor growth / cancer-cell effects','Inhibited cancer-cell growth and suppressed tumor growth; study reports dual signaling pathways','PMID 29763387','Curated' FROM peptides p JOIN cell_lines cl ON cl.cell_line_name='DU-145' JOIN publications pub ON pub.pmid='29763387' WHERE p.public_id='LIT-LYCOSIN-I' AND NOT EXISTS (SELECT 1 FROM activity_assays a WHERE a.peptide_id=p.peptide_id AND a.cell_line_id=cl.cell_line_id AND a.publication_id=pub.publication_id);
SELECT p.peptide_id,cl.cell_line_id,pub.publication_id,'Cell migration / invasion assays','Antitumor activity','Inhibited stemness, EMT, migration and invasion in MCF-7 and MDA-MB-231 models','PMID 30740360','Curated' FROM peptides p JOIN cell_lines cl ON cl.cell_line_name='MCF-7' JOIN publications pub ON pub.pmid='30740360' WHERE p.public_id='LIT-BMK-AGAP' AND NOT EXISTS (SELECT 1 FROM activity_assays a WHERE a.peptide_id=p.peptide_id AND a.cell_line_id=cl.cell_line_id AND a.publication_id=pub.publication_id);
SELECT p.peptide_id,cl.cell_line_id,pub.publication_id,'Cell migration / invasion assays','Antitumor activity','Inhibited stemness, EMT, migration and invasion in MCF-7 and MDA-MB-231 models','PMID 30740360','Curated' FROM peptides p JOIN cell_lines cl ON cl.cell_line_name='MDA-MB-231' JOIN publications pub ON pub.pmid='30740360' WHERE p.public_id='LIT-BMK-AGAP' AND NOT EXISTS (SELECT 1 FROM activity_assays a WHERE a.peptide_id=p.peptide_id AND a.cell_line_id=cl.cell_line_id AND a.publication_id=pub.publication_id);

-- Mechanism evidence
SELECT p.peptide_id,m.mechanism_id,pub.publication_id,cl.cell_line_id,'Primary experimental study','Lycosin-I activates mitochondrial death signaling and promotes apoptosis; p27 up-regulation was also reported.','PMID 22882120','Curated' FROM peptides p JOIN mechanisms m ON m.mechanism_name='Mitochondrial death pathway' JOIN publications pub ON pub.pmid='22882120' LEFT JOIN cell_lines cl ON cl.cell_line_name='DU-145' WHERE p.public_id='LIT-LYCOSIN-I' AND NOT EXISTS (SELECT 1 FROM peptide_mechanisms x WHERE x.peptide_id=p.peptide_id AND x.mechanism_id=m.mechanism_id);
SELECT p.peptide_id,m.mechanism_id,pub.publication_id,cl.cell_line_id,'Primary experimental study','Smp24 activity was associated with membrane disruption and mitochondrial dysfunction, with cell-cycle arrest, apoptosis and autophagy.','Toxins 2022','Curated' FROM peptides p JOIN mechanisms m ON m.mechanism_name='Membrane disruption' JOIN publications pub ON pub.doi='10.3390/toxins14100717' JOIN cell_lines cl ON cl.cell_line_name='HepG2' WHERE p.public_id='LIT-SMP24' AND NOT EXISTS (SELECT 1 FROM peptide_mechanisms x WHERE x.peptide_id=p.peptide_id AND x.mechanism_id=m.mechanism_id);
SELECT p.peptide_id,m.mechanism_id,pub.publication_id,'Primary experimental study','Crotamine cytotoxicity involved calcium release and loss of mitochondrial membrane potential.','DOI 10.1021/mp2000605','Curated' FROM peptides p JOIN mechanisms m ON m.mechanism_name='Calcium / mitochondrial pathway' JOIN publications pub ON pub.doi='10.1021/mp2000605' WHERE p.public_id='LIT-CROTAMINE' AND NOT EXISTS (SELECT 1 FROM peptide_mechanisms x WHERE x.peptide_id=p.peptide_id AND x.mechanism_id=m.mechanism_id);
SELECT p.peptide_id,m.mechanism_id,pub.publication_id,'Primary experimental study','Chlorotoxin was shown to impair glioma invasion through interaction with matrix metalloproteinase-2.','DOI 10.1074/jbc.M205662200','Curated' FROM peptides p JOIN mechanisms m ON m.mechanism_name='Invasion inhibition' JOIN publications pub ON pub.doi='10.1074/jbc.M205662200' WHERE p.public_id='LIT-CHLOROTOXIN' AND NOT EXISTS (SELECT 1 FROM peptide_mechanisms x WHERE x.peptide_id=p.peptide_id AND x.mechanism_id=m.mechanism_id);
SELECT p.peptide_id,m.mechanism_id,pub.publication_id,'Primary experimental study','BmK AGAP inhibited cancer-cell stemness, EMT, migration and invasion through PTX3-associated NF-kB and Wnt/beta-catenin signaling.','PMID 30740360','Curated' FROM peptides p JOIN mechanisms m ON m.mechanism_name='EMT / stemness modulation' JOIN publications pub ON pub.pmid='30740360' WHERE p.public_id='LIT-BMK-AGAP' AND NOT EXISTS (SELECT 1 FROM peptide_mechanisms x WHERE x.peptide_id=p.peptide_id AND x.mechanism_id=m.mechanism_id);

-- Verified experimental structure link. The deposited PDB construct contains an N-terminal extension relative to the 36-aa mature sequence used above.
SELECT p.peptide_id,'7X41','Chlorotoxin','A','X-RAY DIFFRACTION',1.15,'Construct differs','https://www.rcsb.org/structure/7X41',CURRENT_DATE FROM peptides p WHERE p.public_id='LIT-CHLOROTOXIN' AND NOT EXISTS (SELECT 1 FROM structures s WHERE s.peptide_id=p.peptide_id AND s.pdb_id='7X41');

-- Audit records
SELECT 'peptides',p.peptide_id,'verification_status','Verified','Primary publication',p.public_id,pub.source_url,'VenomOncoDB','Seeded','Natural venom source and anticancer evidence are traceable to the cited primary literature.' FROM peptides p JOIN publications pub ON pub.pmid='29763387' WHERE p.public_id='LIT-LYCOSIN-I';


-- Global snake-venom species reference catalogue (reference-only; not anticancer claims).
-- Global snake-venom species reference catalogue. These rows are NOT claims of anticancer activity.
CREATE TABLE IF NOT EXISTS snake_venom_catalog (
 catalog_id INT AUTO_INCREMENT PRIMARY KEY,
 scientific_name VARCHAR(255) NOT NULL UNIQUE,
 common_name VARCHAR(255) NOT NULL,
 record_type VARCHAR(80) NOT NULL DEFAULT 'Snake venom source reference',
 anticancer_evidence_status VARCHAR(100) NOT NULL DEFAULT 'Not established in this catalogue',
 evidence_note TEXT NOT NULL,
 taxonomy_reference VARCHAR(500) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ON DUPLICATE KEY UPDATE common_name=VALUES(common_name), record_type=VALUES(record_type), anticancer_evidence_status=VALUES(anticancer_evidence_status), evidence_note=VALUES(evidence_note), taxonomy_reference=VALUES(taxonomy_reference);
