INSERT INTO mechanisms(mechanism_name,description) VALUES
('Apoptosis','Programmed cell death reported in the cited experimental study.'),
('Mitochondrial death pathway','Mitochondrial pathway involvement reported in the cited study.'),
('Membrane disruption','Loss/damage of cancer-cell membrane integrity reported experimentally.'),
('Invasion inhibition','Reduced tumor-cell invasion/migration reported in the cited study.'),
('EMT / stemness modulation','Changes in epithelial-mesenchymal transition or cancer stemness reported in the cited study.'),
