(NULL,'10.3390/toxins14100717','Smp24, a Scorpion-Venom Peptide, Exhibits Potent Antitumor Effects against Hepatoma HepG2 Cells via Multi-Mechanisms In Vivo and In Vitro','Toxins',2022,'Primary research','https://pmc.ncbi.nlm.nih.gov/articles/PMC9607800/'),
('30740360','10.3389/fonc.2019.00021','Scorpion Venom Analgesic Peptide, BmK AGAP Inhibits Stemness, and Epithelial-Mesenchymal Transition by Down-Regulating PTX3 in Breast Cancer','Frontiers in Oncology',2019,'Primary research','https://pubmed.ncbi.nlm.nih.gov/30740360/'),
('21834748','10.1517/13543784.2011.602064','Crotamine toxicity and efficacy in mouse models of melanoma','Expert Opinion on Investigational Drugs',2011,'Primary research','https://pubmed.ncbi.nlm.nih.gov/21834748/'),
(NULL,'10.1021/mp2000605','The Natural Cell-Penetrating Peptide Crotamine Targets Tumor Tissue in Vivo and Triggers a Lethal Calcium-Dependent Pathway in Cultured Cells','Molecular Pharmaceutics',2012,'Primary research','https://pubs.acs.org/doi/10.1021/mp2000605'),
('9809993',NULL,'Use of chlorotoxin for targeting of primary brain tumors','Cancer Research',1998,'Primary research','https://pubmed.ncbi.nlm.nih.gov/9809993/'),
(NULL,'10.1074/jbc.M205662200','Chlorotoxin Inhibits Glioma Cell Invasion via Matrix Metalloproteinase-2','Journal of Biological Chemistry',2003,'Primary research','https://www.sciencedirect.com/science/article/pii/S0021925819308300')
